TASK
Collect the first requested number of eligible fulfilled input values.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pSome (CommonJS), with pSome.AggregateError.
pSome(input, {count, filter?}) returns a cancelable Promise. input is an iterable of promises or ordinary values. It fulfills once count eligible values have fulfilled, with an array in fulfillment order. count is a finite number with minimum 1 and cannot exceed the number of input items. The optional synchronous filter(value) determines whether a fulfilled value is eligible; omitted filter accepts all values. If count becomes impossible, the operation rejects rather than waiting indefinitely. Rejected input errors are represented by AggregateError. Inputs that are still pending and have a .cancel() method are canceled when the operation settles; calling .cancel() on the result cancels pending inputs too.

SOURCE index.js
   1: 'use strict';
   2: const AggregateError = require('aggregate-error');
   3: const PCancelable = require('p-cancelable');
   4: 
   5: class FilterError extends Error { }
   6: 
   7: const pSome = (iterable, options) => new PCancelable((resolve, reject, onCancel) => {
   8: 	const {count, filter = () => true} = options;
   9: 
  10: 	if (!Number.isFinite(count)) {
  11: 		reject(new TypeError(`Expected a finite number, got ${typeof options.count}`));
  12: 		return;
  13: 	}
  14: 
  15: 	const values = [];
  16: 	const errors = [];
  17: 	let elementCount = 0;
  18: 	let isSettled = false;
  19: 
  20: 	const completed = new Set();
  21: 	const maybeSettle = () => {
  22: 		if (values.length === count) {
  23: 			resolve(values);
  24: 			isSettled = true;
  25: 		}
  26: 
  27: 		if (elementCount - errors.length < count) {
  28: 			reject(new AggregateError(errors));
  29: 			isSettled = true;
  30: 		}
  31: 
  32: 		return isSettled;
  33: 	};
  34: 
  35: 	const cancelPending = () => {
  36: 		for (const promise of iterable) {
  37: 			if (!completed.has(promise) && typeof promise.cancel === 'function') {
  38: 				promise.cancel();
  39: 			}
  40: 		}
  41: 	};
  42: 
  43: 	onCancel(cancelPending);
  44: 
  45: 	for (const element of iterable) {
  46: 		elementCount++;
  47: 		(async () => {
  48: 			try {
  49: 				const value = await element;
  50: 				if (isSettled) {
  51: 					return;
  52: 				}
  53: 
  54: 				if (!filter(value)) {
  55: 					throw new FilterError('Value does not satisfy filter');
  56: 				}
  57: 
  58: 				values.push(value);
  59: 			} catch (error) {
  60: 				errors.push(error);
  61: 			} finally {
  62: 				completed.add(element);
  63: 				if (!isSettled && maybeSettle()) {
  64: 					cancelPending();
  65: 				}
  66: 			}
  67: 		})();
  68: 	}
  69: 
  70: 	if (count > elementCount) {
  71: 		reject(new RangeError(`Expected input to contain at least ${options.count} items, but contains ${elementCount} items`));
  72: 		cancelPending();
  73: 	}
  74: });
  75: 
  76: module.exports = pSome;
  77: // TODO: Remove this for the next major release
  78: module.exports.default = pSome;
  79: 
  80: module.exports.AggregateError = AggregateError;
  81: module.exports.FilterError = FilterError;

